changeSet.sql:
UPDATE teacher_inline_comment SET type = 'COMMENT' WHERE lower(type) = 'comment';

UPDATE teacher_inline_comment SET type = 'SUGGESTION' WHERE lower(type) = 'suggestion';

UPDATE teacher_inline_comment
SET type = CASE
    WHEN suggested_code IS NOT NULL AND suggested_code <> '' THEN 'SUGGESTION'
    ELSE 'COMMENT'
END
WHERE type NOT IN ('COMMENT', 'SUGGESTION');

DELETE FROM student_moodle_pending_course_group_access g
USING course c
WHERE c.id = g.course_id AND c.moodle_short_name IS NULL;

DELETE FROM student_moodle_pending_access p
USING course c
WHERE c.id = p.course_id AND c.moodle_short_name IS NULL;

DELETE FROM student_moodle_pending_course_group_access g
WHERE NOT EXISTS (
    SELECT 1 FROM student_moodle_pending_access p
    WHERE p.course_id = g.course_id AND p.moodle_username = g.moodle_username
);
